// Parse coordination request
const request = $input.first().json;

// Required fields validation
if (!request.action || !request.proposal || !request.requesting_agent) {
  return [{
    json: {
      error: 'Missing required fields: action, proposal, requesting_agent',
      status: 'invalid'
    }
  }];
}

// Create coordination session
const sessionId = `coord_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const coordinationData = {
  ...request,
  session_id: sessionId,
  created_at: new Date().toISOString(),
  status: 'pending',
  voting_required: true,
  voting_threshold: request.voting_threshold || 0.6,
  timeout_minutes: request.timeout_minutes || 15,
  current_votes: {},
  participants: request.participants || ['agent_dungeon_master', 'agent_narrator', 'agent_combat_manager', 'agent_scene_coordinator']
};

return [{
  json: coordinationData
}];

// Process voting request
const coordination = $input.first().json;

// Create voting ballots for each participant
const votingBallots = coordination.participants.map(participant => ({
  session_id: coordination.session_id,
  proposal: coordination.proposal,
  voting_agent: participant,
  vote_options: ['approve', 'reject', 'abstain', 'conditional'],
  vote_deadline: new Date(Date.now() + coordination.timeout_minutes * 60000).toISOString(),
  voting_weight: coordination.voting_weights ? coordination.voting_weights[participant] : 1,
  vote_cast: null,
  vote_reason: null,
  status: 'pending'
}));

// Broadcast voting request to all participants
return votingBallots.map(ballot => ({
  json: {
    type: 'voting_request',
    to_agent: ballot.voting_agent,
    from_agent: 'party_coordinator',
    data: ballot,
    message: `Voting request: ${coordination.proposal.title || 'New proposal'}\n\n${coordination.proposal.description}\n\nPlease vote by: ${ballot.vote_deadline}`
  }
}));

// Process direct coordination (no voting required)
const coordination = $input.first().json;

if (coordination.action === 'consensus') {
  return [{
    json: {
      type: 'consensus_request',
      session_id: coordination.session_id,
      proposal: coordination.proposal,
      requesting_agent: coordination.requesting_agent,
      participants: coordination.participants,
      status: 'seeking_consensus',
      deadline: new Date(Date.now() + coordination.timeout_minutes * 60000).toISOString()
    }
  }];
}

return [{
  json: {
    type: 'direct_coordination',
    session_id: coordination.session_id,
    status: 'processing'
  }
}];

// Store coordination session
const coordination = $input.first().json;

const sessionData = {
  session_id: coordination.session_id,
  action: coordination.action,
  proposal: coordination.proposal,
  requesting_agent: coordination.requesting_agent,
  participants: coordination.participants,
  voting_threshold: coordination.voting_threshold,
  status: coordination.status,
  created_at: coordination.created_at,
  timeout_minutes: coordination.timeout_minutes,
  deadline: new Date(Date.now() + coordination.timeout_minutes * 60000).toISOString()
};

return [{
  json: sessionData
}];

// Schedule voting deadline check
const coordination = $input.first().json;
const delayMinutes = coordination.timeout_minutes || 15;

// Create delayed execution for vote counting
return [{
  json: {
    session_id: coordination.session_id,
    action: 'count_votes',
    scheduled_for: new Date(Date.now() + delayMinutes * 60000).toISOString(),
    status: 'scheduled'
  }
}];

